const $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shop='https://fireflyeventrentals.com';
const packages={
 standard:{name:'The Standard',tag:'THE EVERYDAY CELEBRATION',description:'Simple, welcoming, and ready for your people.',image:'assets/packages-4.jpeg',imageClass:'standard-crop',alt:'White folding chairs and round tables with white linens',features:['White plastic folding chairs','Round tables with white linens','Rectangle tables with white linens'],variants:[{guests:56,price:250.20,slug:'56-guest-package-standard',items:['56 white plastic folding chairs','7 five-foot round tables (8 seats each)','7 white 108-inch round linens','2 six-foot rectangle tables','2 white 60 × 102-inch rectangle linens']},{guests:72,price:329.40,slug:'72-guest-package-standard'},{guests:150,price:631.50,slug:'150-guest-package-standard'}]},
 deluxe:{name:'The Deluxe',tag:'A CLASSIC WITH A LITTLE EXTRA',description:'An inviting setting, with the details brought together.',image:'assets/home-4.jpeg',alt:'Round tables and resin chairs arranged outdoors',features:['Brown resin folding chairs','Round tables with white linens','Rectangle & cocktail tables with linens'],variants:[{guests:50,price:301.50,slug:'50-guest-package-deluxe',items:['50 brown resin folding chairs','5 six-foot round tables (10 seats each)','5 white 120-inch round linens','2 six-foot rectangle tables','2 white 60 × 102-inch rectangle linens','1 folding cocktail table (32 × 42 inches)','1 white 108-inch round linen']},{guests:70,price:436.50,slug:'70-guest-package-deluxe',items:['70 brown resin folding chairs','7 six-foot round tables (10 seats each)','7 white 120-inch round linens','3 six-foot rectangle tables','3 white 60 × 102-inch rectangle linens','2 folding cocktail tables (32 × 42 inches)','2 white 108-inch round linens']},{guests:150,price:850.50,slug:'150-guest-package-deluxe'}]},
 farmhouse:{name:'The Farmhouse',tag:'NATURAL WARMTH. LASTING IMPRESSIONS.',description:'Wood textures and an easy, gathered-around feeling.',image:'assets/home-17.jpg',alt:'A wooden farmhouse table styled for an outdoor celebration',features:['Wood farmhouse tables','Brown resin folding chairs','Rectangle tables with white linens'],variants:[{guests:50,price:433.50,slug:'50-guest-package-farmhouse',items:['50 brown resin folding chairs','5 wood farmhouse foldable tables','2 six-foot rectangle tables','2 white 60 × 102-inch rectangle linens']},{guests:70,price:610.50,slug:'70-guest-package-farmhouse'},{guests:150,price:1264.50,slug:'150-guest-package-farmhouse'}]}
};
// Original package artwork and verified bundle contents, kept together by variant.
packages.deluxe.image='assets/packages-1.jpeg';
packages.deluxe.alt='Original Deluxe package with brown resin folding chairs and white-covered round tables';
packages.farmhouse.image='assets/packages-7.jpeg';
packages.standard.imageClass='';
