packages.standard.variants[2].items=['150 white plastic folding chairs','18 five-foot round tables (8 seats each)','18 white 108-inch round linens','4 six-foot rectangle tables','4 white 60 × 102-inch rectangle linens'];
packages.deluxe.variants[2].items=['150 brown resin folding chairs','15 six-foot round tables (10 seats each)','15 white 120-inch round linens','4 six-foot rectangle tables','4 white 60 × 102-inch rectangle linens','2 folding cocktail tables (32 × 42 inches)','2 white 108-inch round linens'];
const itemPhotos=[
 [/plastic folding/i,'white-plastic-folding-chair.webp'],
 [/resin folding/i,'brown-resin-folding-chair.webp'],
 [/five-foot round/i,'5-foot-round-table.webp'],
 [/six-foot round/i,'6-foot-round-table.webp'],
 [/108-inch/i,'white-108-round-linen.webp'],
 [/120-inch/i,'white-120-round-linen.webp'],
 [/rectangle linen/i,'white-60x102-rectangle-linen.webp'],
 [/rectangle table/i,'6-foot-rectangle.png'],
 [/cocktail/i,'cocktail-table-high-boy-foldable.webp'],
 [/farmhouse/i,'wood-farmhouse-foldable-tables.webp']
];
const itemPhoto=label=>{const match=itemPhotos.find(([pattern])=>pattern.test(label));return match?'assets/catalog/'+match[1]:null;};
Object.entries(packages).forEach(([key,p])=>p.variants.forEach((v,i)=>{v.image=`assets/packages-${({standard:4,deluxe:1,farmhouse:7})[key]+i}.jpeg`;}));
let guestIndex=0;
function renderPackages(){
 $('#package-grid').innerHTML=Object.entries(packages).map(([key,p])=>{const v=p.variants[guestIndex];return `<article class="package-card"><button class="package-picture package-artwork" data-package="${key}" aria-label="View ${p.name} for ${v.guests} guests"><img src="${({standard:'assets/home-4.jpeg',deluxe:'assets/home-20.jpg',farmhouse:'assets/home-17.jpg'})[key]}" alt="${p.name} event inspiration; see details for included rentals" loading="lazy"><span class="guest-badge">${v.guests} guests</span></button><div class="package-body"><div class="card-eyebrow">${p.tag}</div><h3>${p.name}</h3><p class="package-description">${p.description}</p><ul class="package-features">${p.features.map(x=>`<li>${x}</li>`).join('')}</ul><div class="package-price"><div><strong>${money(v.price)}</strong><span> / 1 day</span></div><small>DIY rental · ${v.guests} guests</small></div><button class="button ${key==='deluxe'?'button-dark':'button-outline'}" data-package="${key}">View package <span aria-hidden="true">↗</span></button></div></article>`;}).join('');
 $('#package-status').textContent=`Showing three package styles for ${[50,70,150][guestIndex]} guests. Standard package includes chairs for ${packages.standard.variants[guestIndex].guests}.`;
}
function chooseGuests(guests){const i=[50,70,150].indexOf(Number(guests));if(i<0)throw Error('Choose 50, 70, or 150 guests.');guestIndex=i;if($('#hero-guests'))$('#hero-guests').value=String(guests);$$('[data-guests]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.guests)===Number(guests))));renderPackages();return{guests:Number(guests),packages:Object.entries(packages).map(([style,p])=>({style,...p.variants[i]}))};}
function openPackage(key){const p=packages[key];if(!p)throw Error('Unknown package style.');const v=p.variants[guestIndex];$('#package-detail').innerHTML=`<div class="detail-image original-package-image"><img src="${v.image}" alt="${p.alt}"></div><div class="detail-body"><div class="eyebrow">${v.guests} GUESTS · ${p.tag}</div><h2 id="detail-title">${p.name}</h2><p>${p.description}</p><div class="detail-price">${money(v.price)}<span> / one-day DIY rental</span></div><h3>What’s included</h3><ul class="detail-items">${(v.items||p.features).map(x=>`<li>${itemPhoto(x)?`<button type="button" class="item-photo" data-item-image="${itemPhoto(x)}" aria-label="View photo of ${escape(x)}"><img src="${itemPhoto(x)}" alt=""></button>`:''}<span>${x}</span></li>`).join('')}</ul>${v.items?'':'<p class="form-note">See the full quantities for this guest count in our booking store.</p>'}<div class="detail-note"><strong>Make it yours.</strong> ${key==='farmhouse'?'Ask about a bench upgrade, extra guests, or finishing touches.':'Add tents, lighting, a dance floor, or other individual rentals.'} Delivery, setup, takedown, and applicable tax are additional. Styling shown is not included unless listed.</div><a class="button button-dark full-width" href="${shop}/products/${v.slug}">Check dates & reserve <span aria-hidden="true">↗</span></a><p class="form-note">Continues to Firefly’s booking store for live availability, final pricing, and payment.</p><button class="text-link plain-button" data-inquiry="${v.guests}-guest ${p.name}">Customize this package <span aria-hidden="true">→</span></button></div>`;$('#package-detail').querySelectorAll('[data-item-image]').forEach(button=>button.addEventListener('click',()=>{const img=$('#package-detail .detail-image img');img.src=button.dataset.itemImage;img.alt=button.getAttribute('aria-label');}));const reset=document.createElement('button');reset.className='package-photo-reset';reset.textContent='View package photo';reset.addEventListener('click',()=>{const img=$('#package-detail .detail-image img');img.src=v.image;img.alt=p.alt;});$('#package-detail .detail-image').append(reset);$('#package-dialog').showModal();document.body.classList.add('dialog-open');return{style:key,...v};}
function syncDialogLock(){document.body.classList.toggle('dialog-open',!!$('dialog[open]'));}
function closeDialog(d){d.close();syncDialogLock();}
$$('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>closeDialog(d));d.addEventListener('close',syncDialogLock);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);}});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-package]');if(b)openPackage(b.dataset.package);const g=e.target.closest('[data-guests]');if(g)chooseGuests(g.dataset.guests);const q=e.target.closest('[data-inquiry]');if(q)openInquiry(q.dataset.inquiry);});
renderPackages();
$('#hero-planner')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#hero-guests').value;if(value==='custom'){openInquiry('Custom package');return;}chooseGuests(value);$('#packages').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
$('.menu-toggle').addEventListener('click',()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Close menu':'Open menu');});
$$('#mobile-nav a').forEach(a=>a.addEventListener('click',()=>{$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open menu');}));
let catalog;
let catalogCategory='all';
const categoryFallback=[['tables','Tables','assets/home-5.jpeg'],['seating','Chairs & seating','assets/home-6.jpg'],['tents','Tents','assets/home-7.jpg'],['dance-floo','Dance floors','assets/home-8.jpeg'],['lighting','Lighting','assets/home-9.webp'],['table-linens','Linens','assets/home-10.jpg'],['backdrops','Backdrops','assets/home-11.webp'],['games','Games','assets/home-14.png'],['sound-system','Audio & visual','assets/home-15.jpeg'],['decor','Decor','assets/home-16.jpeg']].map(([slug,name,image])=>({slug,name,image}));
function showCategories(cats){$('#category-grid').innerHTML=cats.map(c=>`<button class="category" data-category="${c.slug}"><span class="category-image"><img src="${c.image}" alt="" loading="lazy"></span><span>${c.name}<i aria-hidden="true">↗</i></span></button>`).join('');}
showCategories(categoryFallback);
const catalogReady=(window.FIREFLY_CATALOG ? Promise.resolve(window.FIREFLY_CATALOG) : fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json();})).then(data=>{catalog=data;showCategories(catalog.categories);$('#product-category').innerHTML='<option value="all">All rentals</option>'+catalog.categories.map(c=>`<option value="${c.slug}">${escape(c.name)}</option>`).join('');}).catch(()=>{$('#catalog-count').textContent='The collection could not load. Browse the booking store or try again.';$('#product-grid').innerHTML=`<a class="button button-dark" href="${shop}/collections/all">Browse the booking store ↗</a>`;});
async function openCatalog(category='all'){if(category!=='all'&&!categoryFallback.some(c=>c.slug===category))throw Error('Unknown rental category.');await catalogReady;catalogCategory=category;$('#catalog').hidden=false;$('#product-category').value=category;$('#product-search').value='';renderProducts();$('#catalog').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return{category,count:filteredProducts().length};}
function filteredProducts(){if(!catalog)return[];const query=$('#product-search').value.toLowerCase().trim();const sort=$('#product-sort').value;return catalog.products.filter(p=>(catalogCategory==='all'||p.categories.includes(catalogCategory))&&p.name.toLowerCase().includes(query)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):((Number(a.price?.replace(/[^\d.]/g,''))||0)-(Number(b.price?.replace(/[^\d.]/g,''))||0))*(sort==='price-asc'?1:-1));}
function renderProducts(){if(!catalog)return;const products=filteredProducts();$('#catalog-title').textContent=catalogCategory==='all'?'All rentals':catalog.categories.find(c=>c.slug===catalogCategory)?.name;$('#catalog-count').textContent=`${products.length} ${products.length===1?'rental':'rentals'} found`;$('#product-grid').innerHTML=products.length?products.map(p=>`<a class="product-card" href="${escape(p.url)}"><div class="product-image"><img src="${p.image}" alt="${escape(p.name)}" loading="lazy"></div><h4>${escape(p.name)}</h4><p><strong>${escape(p.price||'Request pricing')}</strong>${p.price?` <span>/ ${escape(p.period)}</span>`:''}</p><span class="product-book">Check dates & details ↗</span></a>`).join(''):'<div class="empty-state"><h4>No rentals match that search.</h4><p>Try a different name or choose “All rentals.”</p><button class="button button-outline" id="reset-search">Clear search</button></div>';$('#reset-search')?.addEventListener('click',()=>{$('#product-search').value='';catalogCategory='all';$('#product-category').value='all';renderProducts();});}
$('#category-grid').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b)openCatalog(b.dataset.category);});$('#browse-all').addEventListener('click',()=>openCatalog());$('#close-catalog').addEventListener('click',()=>{$('#catalog').hidden=true;$('#browse-all').focus();});$('#product-search').addEventListener('input',renderProducts);$('#product-category').addEventListener('change',()=>{catalogCategory=$('#product-category').value;renderProducts();});$('#product-sort').addEventListener('change',renderProducts);
function openInquiry(subject){$$('dialog[open]').forEach(closeDialog);$('#inquiry-form').hidden=false;$('#inquiry-result').hidden=true;const form=$('#inquiry-form');form.elements.guests.value=subject.match(/^(\d+)-guest /)?.[1]||[50,70,150][guestIndex];$('#copy-status').textContent='';if(subject.includes('Deluxe'))form.elements.style.value='Deluxe';else if(subject.includes('Farmhouse'))form.elements.style.value='Farmhouse';else if(subject.includes('Standard'))form.elements.style.value='Standard';else form.elements.style.value='Help me choose';form.elements.notes.value=subject==='Custom package'?'':`I’d like help with ${subject.toLowerCase()}.`;$('#inquiry-dialog').showModal();document.body.classList.add('dialog-open');}
const today=new Date();const localToday=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;$('#inquiry-form').elements.date.min=localToday;
// Refresh validation after midnight and reject whitespace-only contact details.
$('#inquiry-form').addEventListener('input',e=>{if(e.target.matches('[name="name"],[name="venue"]'))e.target.setCustomValidity(e.target.value.trim()?'':'Please enter a value.');});
$('#inquiry-form').addEventListener('focusin',()=>{const now=new Date();$('#inquiry-form').elements.date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open menu');$('.menu-toggle').focus();}});
$('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const message=`Hi Firefly! I’d like help planning an event.\n\nName: ${data.name}\nEvent date: ${data.date}\nGuests: ${data.guests}\nVenue / city: ${data.venue}\nRental style: ${data.style}\nService: ${data.service}\n\n${data.notes}\n\nPlease confirm availability and send a quote, including any delivery, setup, takedown, and tax.`;$('#inquiry-message').textContent=message;$('#send-email').href=`mailto:fireflyeventrentals@gmail.com?subject=${encodeURIComponent('Event rental inquiry — '+data.date)}&body=${encodeURIComponent(message)}`;$('#send-text').href=`sms:+13856458996?body=${encodeURIComponent(message)}`;$('#inquiry-form').hidden=true;$('#inquiry-result').hidden=false;$('#send-email').focus();});
$('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#inquiry-message').textContent);$('#copy-status').textContent='Copied. Paste it into your email or text message.';}catch{$('#copy-status').textContent='Select and copy the message above to send it.';}});$('#edit-inquiry').addEventListener('click',()=>{$('#inquiry-form').hidden=false;$('#inquiry-result').hidden=true;$('#inquiry-form').elements.name.focus();});
$$('[data-photo]').forEach(b=>b.addEventListener('click',()=>{$('#photo-full').src=b.dataset.photo;$('#photo-full').alt=b.dataset.caption;$('#photo-caption').textContent=b.dataset.caption;$('#photo-dialog').showModal();document.body.classList.add('dialog-open');}));$('#year').textContent=today.getFullYear();
// Hero gestures and motion live in fluid-carousel.js.
// Tools share the same state as the visible comparison and collection controls.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'compare_rental_packages',title:'Compare Firefly packages',description:'Choose a guest-count group and update the visible package comparison. Does not check availability or reserve items.',inputSchema:{type:'object',properties:{guests:{type:'integer',enum:[50,70,150]}},required:['guests'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.guests!=='number'||Object.keys(input).some(k=>k!=='guests'))throw Error('Provide only guests as 50, 70, or 150.');return chooseGuests(input.guests);}},{name:'show_rental_collection',title:'Browse Firefly rentals',description:'Open an individual rental category in the visible catalog. Does not create an order.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['all',...categoryFallback.map(c=>c.slug)]}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.category!=='string'||Object.keys(input).some(k=>k!=='category'))throw Error('Provide a category.');return openCatalog(input.category);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
